def weighted_sample_stream(items, weights, k, draws, seed=0, start=0):
    """weighted_sample 的按需逐轮入口, 规则与
    weighted_sample_stream_indices 完全一致(含 start 窗口语义), 区别
    仅在于每轮按相同索引产出元素值列表; 与 weighted_sample_many 的逐轮
    结果完全一致。
    """
