        items, weights, k, draws, seed, start
    )
    return ([items[i] for i in round_indices] for round_indices in index_stream)


# ---------------------------------------------------------------------------
# 可暂停 / 恢复的采样会话
# ---------------------------------------------------------------------------

# 状态格式版本: 状态结构发生不兼容变化时递增; 恢复时只接受当前版本。
_CHECKPOINT_VERSION = 1


def _hash_text(text):
    """对文本取 sha256, 返回与 json.loads 往返一致的 hexdigest 字符串。"""
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _weight_fingerprint_text(index, weight):
    """把单个权重规范化为参与指纹计算的文本行。

    行首的类型标签保证不同类型的同值权重(如 1 与 1.0、Decimal('1') 与
    Fraction(1, 1))不被视为同一输入 —— 它们可能走不同抽样路径; 同类型
    同值才逐字相同。判定只针对已通过 _validate_sample_inputs 的权重
    (非 bool、int/float/Fraction/Decimal、有限非负), 不会触发 decimal
    比较异常; Fraction 与大整数全程按精确有理值/十进制值处理, 不经过
    浮点, 超大 Decimal 指数同样安全。
    """
    if isinstance(weight, bool):  # 防御性: bool 已在输入校验中拒绝
        return "%d:b:%d" % (index, int(weight))
    if isinstance(weight, int):
        return "%d:i:%s" % (index, _int_to_decimal_text(weight))
    if isinstance(weight, Fraction):
        return "%d:f:%s/%s" % (
            index,
            _int_to_decimal_text(weight.numerator),
            _int_to_decimal_text(weight.denominator),
        )
    if isinstance(weight, Decimal):
        return "%d:d:%s" % (index, str(Decimal(weight)))
    # 有限非负 float: repr 文本对 -0.0 保留符号, 且往返(float, repr)
    # 精确还原同一二进制浮点值。
    return "%d:r:%s" % (index, float.__repr__(weight))


def _weights_fingerprint(weights):
    """对整个权重序列取指纹: 逐位置规范化后整体 sha256。"""
    body = "\n".join(
        _weight_fingerprint_text(i, w) for i, w in enumerate(weights)
    )
    return _hash_text(body)


def _items_fingerprint(items):
    """对 items 取指纹。

    items 的元素类型不受采样入口约束(可以是任意对象), 故不能假定其可
    JSON 化; 指纹只用于检测同一进程内 items 内容是否与创建断点时一致,
    跨进程恢复由调用方保证传入相同 items(状态本身不承载 items)。
    对每个位置取 (类型标识, repr 文本) 的稳定哈希, 自定义 __repr__ 亦
    按调用方提供的实际状态参与。
    """
    digest = hashlib.sha256()
    for i, item in enumerate(items):
        digest.update(
            ("%d:%s:%r\n" % (i, type(item).__qualname__, item)).encode(
                "utf-8", "backslashreplace"
            )
        )
    return digest.hexdigest()


def _seed_to_tagged_value(seed):
    """把支持的 seed 类型编码为只含 JSON 原生值的 [标签, 载荷] 对。

    标签: n=None; i=int(含 bool, 先于 int 判定单独标记); f=float;
    s=str; b=bytes; y=bytearray。float 的 NaN / ±Inf 不是合法 JSON
    值, 用文本标签 nf/ni/-inf 保留; -0.0 以 -0 保留符号。往返
    (_tagged_value_to_seed) 必须逐值还原 random.Random 实际收到的种子
    对象, bool 不被 int 吞掉。
    """
    if seed is None:
        return ["n", None]
    if isinstance(seed, bool):
        return ["i", 1 if seed else 0, True]
    if isinstance(seed, int):
        return ["i", seed]
    if isinstance(seed, float):
        if math.isnan(seed):
            return ["f", "nan"]
        if math.isinf(seed):
            return ["f", "inf" if seed > 0 else "-inf"]
        return ["f", seed]
    if isinstance(seed, str):
        return ["s", seed]
    if isinstance(seed, bytes):
        return ["b", seed.decode("latin-1")]
    # bytearray: latin-1 对 0..255 字节双向无损。
    return ["y", bytes(seed).decode("latin-1")]


def _tagged_value_to_seed(value):
    """_seed_to_tagged_value 的逆运算; 非法结构抛 ValueError。"""
    if (not isinstance(value, list) or not value
            or not all(not isinstance(x, bool) and isinstance(x, str)
                       for x in value[::2])):
        raise ValueError("invalid checkpoint seed encoding")
    tag = value[0]
    if tag == "n":
        if len(value) != 2 or value[1] is not None:
            raise ValueError("invalid checkpoint seed encoding")
        return None
    if tag == "i":
        if len(value) == 2:
            number = value[1]
            if isinstance(number, bool) or not isinstance(number, int):
                raise ValueError("invalid checkpoint seed encoding")
            return number
        if len(value) == 3 and value[2] is True:
            number = value[1]
            if isinstance(number, bool) or not isinstance(number, int) \
                    or number not in (0, 1):
                raise ValueError("invalid checkpoint seed encoding")
            return bool(number)
        raise ValueError("invalid checkpoint seed encoding")
    if tag == "f":
        if len(value) != 2:
            raise ValueError("invalid checkpoint seed encoding")
        payload = value[1]
        if payload == "nan":
            return float("nan")
        if payload == "inf":
            return float("inf")
        if payload == "-inf":
            return float("-inf")
        if isinstance(payload, bool) or not isinstance(payload, (int, float)):
            raise ValueError("invalid checkpoint seed encoding")
        return float(payload)
    if tag == "s":
        if len(value) != 2 or not isinstance(value[1], str):
            raise ValueError("invalid checkpoint seed encoding")
        return value[1]
    if tag in ("b", "y"):
        if len(value) != 2 or not isinstance(value[1], str):
            raise ValueError("invalid checkpoint seed encoding")
        try:
            raw = value[1].encode("latin-1")
        except UnicodeEncodeError:
            raise ValueError("invalid checkpoint seed encoding")
        return raw if tag == "b" else bytearray(raw)
    raise ValueError("invalid checkpoint seed encoding")


def _rng_state_to_jsonable(state):
    """把 random.Random.getstate() 的三元组编码为 JSON 原生结构。

    getstate() -> (版本 3, 625 个 Python 整数的元组, gauss 缓存标志)。
    其中末项为 None(无缓存)或 float; 这里对 None / float 分别标签化,
    其余整数原样保留(任意位数, 经 serialize_metrics 仍是精确十进制)。
    """
    if (not isinstance(state, tuple) or len(state) != 3
            or state[0] != 3 or not isinstance(state[1], tuple)
            or len(state[1]) != 625):
        raise ValueError("invalid checkpoint RNG state")
    mt = state[1]
    if any(isinstance(x, bool) or not isinstance(x, int) for x in mt):
        raise ValueError("invalid checkpoint RNG state")
    cached = state[2]
    if cached is None:
        cache = ["n", None]
    elif isinstance(cached, bool) or not isinstance(cached, float):
        raise ValueError("invalid checkpoint RNG state")
    elif math.isnan(cached) or math.isinf(cached):
        raise ValueError("invalid checkpoint RNG state")
    else:
        cache = ["f", cached]
    return {"v": 3, "mt": list(mt), "cached": cache}


def _rng_state_from_jsonable(payload):
    """_rng_state_to_jsonable 的逆运算; 非法结构抛 ValueError。"""
    if not isinstance(payload, dict) or set(payload) != {"v", "mt", "cached"}:
        raise ValueError("invalid checkpoint RNG state")
    if payload["v"] != 3 or not isinstance(payload["mt"], list) \
            or len(payload["mt"]) != 625:
        raise ValueError("invalid checkpoint RNG state")
    mt = []
    for x in payload["mt"]:
        if isinstance(x, bool) or not isinstance(x, int):
            raise ValueError("invalid checkpoint RNG state")
        mt.append(x)
    cache_encoded = payload["cached"]
    if (not isinstance(cache_encoded, list) or len(cache_encoded) != 2):
        raise ValueError("invalid checkpoint RNG state")
    label, raw = cache_encoded
    if label == "n":
        if raw is not None:
            raise ValueError("invalid checkpoint RNG state")
        cached = None
    elif label == "f":
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise ValueError("invalid checkpoint RNG state")
        cached = float(raw)
        if not math.isfinite(cached):
            raise ValueError("invalid checkpoint RNG state")
    else:
        raise ValueError("invalid checkpoint RNG state")
    return (3, tuple(mt), cached)


def _prepare_validated_session(items, weights, k, seed, start):
    """两个断点入口共用的前置准备: 与批量入口完全一致的校验与可行性检查。

    返回 (n, pool_weights, use_exact, rng) —— rng 已按与批量入口相同
    的方式由 seed 初始化, 并(在需要产出后续轮次时)先消耗 start 个完整
    轮次, 因此其内部状态恰好对应批量序列中 "start 轮已完成" 的断点。
    """
    n = _validate_sample_inputs(items, weights, k, seed)
    _validate_start(start)

    # 与批量入口相同的可行性前置检查: 即使只是创建断点, k 超过有效正
    # 权重个数也必须在返回任何状态前确定抛 ValueError。
    if k > 0 and k > _count_positive_weights(weights):
        raise ValueError("no positive weight")

    pool_weights = list(weights)
    rng = random.Random(seed)
    pool_weights, use_exact = _select_sampling_plan(pool_weights, k)

    # 与 weighted_sample_many_indices 的跳过逻辑逐字一致: k=0 的轮次不
    # 消耗随机流, start=0 不空转。
    if k > 0:
        for _ in range(start):
            _draw_indices_once(n, pool_weights, k, rng, use_exact)
    return n, pool_weights, use_exact, rng


def weighted_sample_checkpoint(items, weights, k, seed=0, start=0):
    """创建采样会话断点(只含 JSON 原生值的状态映射)。

    校验规则与 weighted_sample_many_indices 完全一致(items、weights、
    k、seed、start 的类型与取值, 以及正权重可行性), 全部通过后把随机
    流推进到已完成 start 轮的位置并快照。返回的状态可直接交给
    serialize_metrics, 也可经 json 文本落盘后在另一进程中交给
    weighted_sample_resume_indices 恢复; 不依赖任何进程内对象身份。
    不修改入参。
    """
    n, pool_weights, use_exact, rng = _prepare_validated_session(
        items, weights, k, seed, start
    )
    return {
        "version": _CHECKPOINT_VERSION,
        "position": start,
        "k": k,
        "n": n,
        "items_digest": _items_fingerprint(items),
        "weights_digest": _weights_fingerprint(weights),
        "seed": _seed_to_tagged_value(seed),
        "exact": bool(use_exact),
        "rng": _rng_state_to_jsonable(rng.getstate()),
    }


def _validate_checkpoint_state(state):
    """校验状态本身的结构与版本。

    状态不是映射抛 TypeError; 字段缺失/类型错误/版本不支持等一切结构
    问题统一抛 ValueError。返回规范化后的字段元组。
    """
    if not isinstance(state, collections.abc.Mapping):
        raise TypeError("checkpoint state must be a mapping")

    required = ("version", "position", "k", "n", "items_digest",
                "weights_digest", "seed", "exact", "rng")
    if not all(key in state for key in required):
        raise ValueError("invalid checkpoint state: missing fields")

    version = state["version"]
    position = state["position"]
    k = state["k"]
    n = state["n"]
    exact = state["exact"]
    if version != _CHECKPOINT_VERSION:
        raise ValueError("unsupported checkpoint version: %r" % (version,))
    for name, value in (("position", position), ("k", k), ("n", n)):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError("invalid checkpoint state: %s" % name)
    if k > n:
        raise ValueError("invalid checkpoint state: k exceeds n")
    if not isinstance(exact, bool):
        raise ValueError("invalid checkpoint state: exact")
    for name in ("items_digest", "weights_digest"):
        value = state[name]
        if not isinstance(value, str):
            raise ValueError("invalid checkpoint state: %s" % name)

    # 下列两个逆运算对内部结构问题统一抛 ValueError。
    seed = _tagged_value_to_seed(state["seed"])
    rng_state = _rng_state_from_jsonable(state["rng"])

    # 拒绝多余字段: 状态必须是本实现产出的已知结构。
    if set(state) != set(required):
        raise ValueError("invalid checkpoint state: unexpected fields")

    return version, position, k, n, exact, seed, rng_state


def weighted_sample_resume_indices(items, weights, k, state, draws):
    """从断点继续产出索引轮次, 返回 (轮次列表, 下一状态)。

    第一轮从断点记录的位置开始; 逐轮结果与
    weighted_sample_many_indices(items, weights, k, draws, seed,
    start=position) 完全一致, 即等于 start=0 完整批量序列的零基区间
    [position, position+draws)。恢复前完成与采样入口一致的全部输入
    校验, 并核对状态与 items、weights、k 是否匹配(同时校验 seed 与
    RNG 快照自洽): 任一不满足, 状态问题抛 ValueError、状态不是映射抛
    TypeError, 且在任何轮次物化之前确定失败, 绝不返回部分轮次。
    draws=0 返回空轮次与内容不变(位置不推进)的新状态; k=0 时每轮为
    空列表, 位置仍逐轮加一。不修改入参。
    """
    # 1. 先按既有规则校验采样输入(items/weights/k —— seed 以状态中的
    #    为准)与 draws。用状态携带的 seed 使校验与断点创建时同源;
    #    状态本身尚不可用时, 这里的类型/取值错误沿用既有异常分类。
    if not isinstance(state, collections.abc.Mapping):
        # 状态类型错误优先按 TypeError 报告, 与文档约定一致。
        _validate_sample_inputs(items, weights, k, 0)
        _validate_draws(draws)
        raise TypeError("checkpoint state must be a mapping")

    # 取状态中的 seed 参与输入校验; 状态结构损坏时统一为 ValueError。
    try:
        _, _, _, _, _, state_seed, _ = _validate_checkpoint_state(state)
    except TypeError:
        # _validate_checkpoint_state 对映射只抛 ValueError; 保留此分支
        # 仅为语义清晰。
        raise
    n = _validate_sample_inputs(items, weights, k, state_seed)
    _validate_draws(draws)

    version, position, state_k, state_n, use_exact, seed, rng_state = (
        _validate_checkpoint_state(state)
    )

    # 2. 状态与当前采样输入的一致性检查(ValueError)。
    if state_k != k or state_n != n:
        raise ValueError("checkpoint state does not match items/weights/k")
    if state["items_digest"] != _items_fingerprint(items):
        raise ValueError("checkpoint state does not match items")
    if state["weights_digest"] != _weights_fingerprint(weights):
        raise ValueError("checkpoint state does not match weights")

    # 3. 正权重可行性与路径必须与创建断点时一致; 权重内容已由指纹
    #    逐位置核对, 这里重建计划并与状态中的 exact 标志比对, 防止
    #    被篡改的状态把 RNG 流按错误路径解释。
    if k > 0 and k > _count_positive_weights(weights):
        raise ValueError("no positive weight")
    pool_weights = list(weights)
    planned_weights, planned_exact = _select_sampling_plan(pool_weights, k)
    if planned_exact != use_exact:
        raise ValueError("invalid checkpoint state: sampling plan mismatch")

    # 4. 校验 RNG 快照与 (seed, position) 自洽: 由 seed 重建随机流并
    #    消耗 position 个完整轮次, 结果必须与快照逐字相等。这样既验证
    #    了 seed 未被篡改, 也验证了位置与 RNG 状态确实对应, 且与从
    #    start=position 重放得到的随机流位置一致。
    replay_rng = random.Random(seed)
    if k > 0:
        for _ in range(position):
            _draw_indices_once(n, planned_weights, k, replay_rng, planned_exact)
    if replay_rng.getstate() != rng_state:
        raise ValueError("invalid checkpoint state: RNG state mismatch")

    # 5. 全部校验通过后才物化轮次: 从快照状态继续, 与批量区间逐轮一致。
    rng = random.Random()
    rng.setstate(rng_state)
    rounds = []
    for _ in range(draws):
        rounds.append(
            _draw_indices_once(n, planned_weights, k, rng, planned_exact)
        )

    next_state = dict(state)
    next_state["position"] = position + draws
    next_state["rng"] = _rng_state_to_jsonable(rng.getstate())
    return rounds, next_state


